frappe.ui.form.on('Item Group Rate Master', {
	item_group: function(frm) {
        if (frm.doc.item_group) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Item Group',
                    filters: {
                        name: frm.doc.item_group
                    },
                    fieldname: 'price'
                },
                callback: function(r) {
                    if (r.message) {
                        price_total=frm.doc.price_master + r.message.price
                        frm.set_value('price_master', price_total);
                    }
                }
            });
        }
    }
})

frappe.ui.form.on('Sales Order Item', {
  item_code: function(frm, cdt, cdn) {
    console.log("Test")  
    let row = locals[cdt][cdn];
    frappe.call({
      method: 'frappe.client.get_list',
      args: {
        doctype: 'Item',
        filters: { name: row.item_code },
        fields: ['item_group']
      },
      callback: function(r) {
        if (r.message && r.message.length > 0) {
          let item_group = r.message[0].item_group;
          frappe.call({
            method: 'frappe.client.get_value',
            args: {
              doctype: 'Item Group Rate Master',
              filters: {
                item_group_master: item_group,
                customer_master: frm.doc.customer
                },
              fieldname: 'price_master'
            },
            callback: function(res) {
              if (res.message) {
                  console.log(res.message)
                frappe.model.set_value(cdt, cdn, 'rate', res.message.price_master);
              }
            }
          });
        }
      }
    });
  }
});


